from pathlib import Path
import re
root=Path('finite-fields-book')
proofs={
(2,12):r'''任意 $a\in G$ 属于 $aH$，故陪集覆盖 $G$。若 $ah_1=bh_2$，则 $a=b(h_2h_1^{-1})$，从而 $aH\subseteq bH$；交换 $a,b$ 得反向包含。所以两个陪集或者相等，或者不交。''',
(3,4):r'''设 $G=\langle a\rangle$，$|G|=m$。子群 $H$ 可写成 $\langle a^d\rangle$，其中 $d$ 是满足 $a^d\in H$ 的最小正整数（$H=\{e\}$ 时取 $d=m$）。对 $m$ 除以 $d$，余数的最小性给出 $d\mid m$；因此 $|H|=m/d$。指定阶 $f\mid m$ 就唯一确定 $d=m/f$，指定指标 $d\mid m$ 也就唯一确定 $H$。''',
(5,6):r'''若 $\deg f<\deg g$，取 $q=0,r=f$。否则，用 $g$ 首项系数的逆选取单项式 $cx^k$，使 $f-cx^kg$ 的次数严格下降，再归纳求商与余式。若 $f=qg+r=q'g+r'$，则 $(q-q')g=r'-r$；非零左端次数至少为 $\deg g$，右端次数却小于 $\deg g$，矛盾。所以商与余式唯一。''',
(6,2):r'''若 $f$ 不可约，对非零剩余类 $a+(f)$，有 $\gcd(a,f)=1$，故存在 $u,v$ 使 $ua+vf=1$，$u+(f)$ 即其逆元。反向分三类：$f=0$ 时商环为 $\mathbb F[x]$，其中 $x$ 不可逆；$f$ 为非零常数时商环为零环，不是域；$f$ 为非零非常数且可约时，两个正次数真因子的剩余类非零而乘积为零，也不是域。''',
(8,7):r'''代入映射的核 $J$ 是非零理想，故由唯一首一多项式 $g$ 生成。若 $g=uv$ 且两因子次数均为正，则 $u(\theta)v(\theta)=0$。扩域是域，故某个因子在 $\theta$ 处为零；该因子属于 $J$，却比 $g$ 次数低，矛盾。因此 $g$ 不可约。''',
(9,4):r'''设 $(u_1,\ldots,u_a)$ 是 $L/K$ 的基，$(v_1,\ldots,v_b)$ 是 $M/L$ 的基。先按 $v_j$ 展开，再将各 $L$ 系数按 $u_i$ 展开，得到 $u_iv_j$ 张成 $M$。若 $\sum_{i,j}c_{ij}u_iv_j=0$，先由 $v_j$ 在 $L$ 上线性无关，再由 $u_i$ 在 $K$ 上线性无关，依次得全部 $c_{ij}=0$。所以这 $ab$ 个乘积构成 $M/K$ 的基。''',
(10,6):r'''令 $q=p^n$，在 $\mathbb F_p$ 上取 $x^q-x$ 的分裂域 $E$，记根集为 $F$。特征 $p$ 的幂公式给出 $(a+b)^q=a+b$、$(ab)^q=ab$；根集中含 $0,1$，并对相反数及非零元素的逆封闭，因此 $F$ 是子域。分裂域由全部根生成，所以 $E=F$。导数为 $-1$，故 $q$ 个根彼此不同，$|F|=q$。任一大小为 $q$ 的域恰含该多项式的全部根，因而也是其分裂域；唯一性是固定素子域的同构意义下唯一。''',
(11,1):r'''更一般地，域的乘法群的任一有限子群 $G$ 都是循环群。令 $E$ 为所有元素阶的最小公倍数。对 $E$ 的每个素数幂因子 $\ell^t$，可从某个元素的幂中取得阶恰为 $\ell^t$ 的元素；将这些元素相乘，因交换性及阶两两互素，所得元素的阶为 $E$。另一方面，$G$ 的全部元素都是 $x^E-1$ 的根，根数界给出 $|G|\leq E$；拉格朗日定理给出 $E\mid |G|$，故 $E=|G|$。取 $G=\mathbb F_q^\ast$ 即得结论。''',
(12,3):r'''令 $d$ 为 $\alpha$ 的 Frobenius 轨道长度。每个轨道元素都是 $f$ 的根，所以 $d\leq m$。乘积 $h(x)=\prod_{j=0}^{d-1}(x-\alpha^{q^j})$ 的系数被 $q$ 次幂固定，因此属于 $\mathbb F_q$；又 $h(\alpha)=0$，故极小多项式 $f$ 的首一化整除 $h$，得到 $m\leq d$。于是 $d=m$，全部根恰是这 $m$ 个不同共轭元。''',
(14,7):r'''令 $M=(\alpha_j^{q^i})_{0\leq i<m,\,1\leq j\leq m}$。迹矩阵的第 $(j,k)$ 项是 $\sum_i\alpha_j^{q^i}\alpha_k^{q^i}$，所以迹矩阵等于 $M^{\mathsf T}M$。其行列式为 $(\det M)^2$，在任何特征下非零当且仅当 $\det M\ne0$；再应用判别式判据即得结论。''',
(17,3):r'''若 $S_i$ 无限，先从中选取 $t_i+1$ 个元素，故只需证明有限情形。反设 $f$ 在整个网格为零，由上一节定理写成 $f=\sum_i h_ig_i$，且 $\deg(h_ig_i)\leq\deg f$。由于 $g_i$ 的首项是 $x_i^{|S_i|}$，其余各项次数更低，最高总次数层只能来自 $h_i$ 与该首项的乘积。这些单项式的 $x_i$ 指数至少为 $|S_i|>t_i$，不可能产生 $\prod_i x_i^{t_i}$，与其系数非零矛盾。''',
(18,1):r'''若 $|A|+|B|>p$，任意 $c\in\mathbb F_p$ 都使 $A$ 与 $c-B$ 相交，因此 $A+B=\mathbb F_p$。否则，若 $|A+B|\leq |A|+|B|-2$，选取含 $A+B$ 的集合 $C$，使 $|C|=|A|+|B|-2<p$。多项式 $P(x,y)=\prod_{c\in C}(x+y-c)$ 在 $A\times B$ 上恒零，但 $x^{|A|-1}y^{|B|-1}$ 的系数为 $\binom{|C|}{|A|-1}\ne0$，组合零点定理给出矛盾。若 $|A|=|B|=1$，结论直接成立。''',
(18,2):r'''也可对任意 $q=p^r$ 证明。公共零点的指示函数为 $\prod_i(1-P_i(x)^{q-1})$。展开后每个单项式的总次数小于 $n(q-1)$，因此至少有一个变量的指数小于 $q-1$。对该变量求和得到 $0$：指数为 $0$ 时总和为 $q=0$，指数在 $1,\ldots,q-2$ 时由乘法群循环性得到幂和为 $0$。逐变量求和可知公共零点数在域中为 $0$，即被特征 $p$ 整除。零多项式可从方程组中删除。''',
(18,7):r'''对序列 $a_1,\ldots,a_{2p-1}$，考虑 $\sum_i x_i^{p-1}=0$ 与 $\sum_i a_ix_i^{p-1}=0$。两式次数之和至多 $2(p-1)<2p-1$，故公共解数被 $p$ 整除。零向量是一个解，所以必有另一个解。非零坐标个数是 $p$ 的正倍数，又不超过 $2p-1$，因此恰为 $p$。每个非零坐标的 $p-1$ 次幂为 $1$，对应的 $p$ 个序列元素之和便为 $0$。一般 $n$ 的情形由章末因子递推练习完成。''',
(19,1):r'''对变量数归纳。一元情形就是根数界。写 $f=\sum_{j=0}^k f_j(x_1,\ldots,x_{n-1})x_n^j$，其中 $f_k\ne0$，且 $\deg f_k\leq d-k$。若 $d\geq|S|$，所需上界已不小于总点数，结论直接成立。否则，由归纳，$f_k$ 为零的前 $n-1$ 个坐标至多有 $(d-k)|S|^{n-2}$ 组；每组至多贡献 $|S|$ 个零点。其余各组上一元多项式非零，至多有 $k$ 个根。合并得到零点数不超过 $d|S|^{n-1}$。'''
}
for (n,b),body in proofs.items():
 p=root/f'chapters/c{n:02}.md';s=p.read_text(encoding='utf-8')
 pattern=rf'(^:::::\{{container\}} statement-box[^\n]*\n:name: c{n:02}-statement-{b:03}\n.*?)(^:::::\s*$)'
 s,count=re.subn(pattern,lambda m:m[1]+'\n```{admonition} 证明（新增）\n:class: dropdown tip\n\n'+body+'\n```\n'+m[2],s,count=1,flags=re.M|re.S)
 assert count==1,(n,b);p.write_text(s,encoding='utf-8')
solutions={
2:(r'证明子群 $H\leq G$ 的两个左陪集若有交集则相等。',r'设 $ah_1=bh_2$，其中 $h_1,h_2\in H$，则 $b^{-1}a=h_2h_1^{-1}\in H$，故 $aH\subseteq bH$；交换两者得反向包含，因而 $aH=bH$。此证明不使用交换律。'),
3:(r'列出 $12$ 阶循环群的全部子群及其生成元个数。',r'对 $f=1,2,3,4,6,12$，唯一的阶为 $f$ 的子群为 $\langle a^{12/f}\rangle$，它们的生成元个数分别为 $1,1,2,2,2,4$。'),
4:(r'取嵌入 $\varphi:\mathbb Z\to\mathbb Q$，检验同态基本定理中的像与陪域。',r'核为 $\{0\}$，像为 $\mathbb Z$，故 $\mathbb Z/\{0\}\cong\mathbb Z$。它不与 $\mathbb Q$ 同构为环，因为 $2$ 在 $\mathbb Q$ 中可逆，在 $\mathbb Z$ 中不可逆。'),
5:(r'在 $\mathbb F_2[x]$ 中将 $x^4+x+1$ 除以 $x^2+x+1$。',r'有 $x^4+x+1=(x^2+x)(x^2+x+1)+1$，所以商为 $x^2+x$，余式为 $1$。'),
6:(r'证明 $x^4+x+1$ 在 $\mathbb F_2$ 上不可约。',r'它在 $0,1$ 处均非零，故无一次因子。唯一首一二次不可约多项式为 $x^2+x+1$，除它的余式为 $1$。四次可约多项式必有一次或二次因子，因此给定多项式不可约。'),
7:(r'写出通过 $\mathbb F_7$ 中 $(0,1),(1,4),(2,2)$ 的次数至多为 $2$ 的插值多项式。',r'答案为 $x^2+2x+1$。代入三点得到 $1,4,2$；节点互异且次数上界为 $2$，故唯一。'),
8:(r'求满足 $\alpha^2=2$ 的元素 $\alpha$ 在 $\mathbb F_3$ 上的极小多项式。',r'$x^2+1$ 在 $\alpha$ 处为零，在 $\mathbb F_3$ 的 $0,1,2$ 处均非零，故不可约。它是首一多项式，因此就是极小多项式。'),
9:(r'说明有限扩张为什么代数，并给出代数但次数无限的扩张。',r'若 $[L:K]=n$，则 $1,\alpha,\ldots,\alpha^n$ 线性相关，给出使 $\alpha$ 归零的非零多项式。$\mathbb F_p$ 的代数闭包是代数扩张，但包含任意大次数的有限子域，故扩张次数不可能有限。'),
10:(r'求固定代数闭包中 $\mathbb F_{2^6}$ 与 $\mathbb F_{2^{10}}$ 的交。',r'交为 $\mathbb F_{2^2}$。交域的次数必须同时整除 $6$ 与 $10$，故整除 $2$；而唯一的二次子域包含于二者。'),
11:(r'给出域扩张的定义元不是本原元的具体例子。',r'取 $\mathbb F_9=\mathbb F_3(\alpha)$，$\alpha^2=2$。$\alpha\notin\mathbb F_3$，因此生成整个二次扩张；但 $\alpha^4=1$ 且 $\alpha^2\ne1$，其乘法阶为 $4$，不是所需的 $8$。'),
12:(r'解释 Frobenius 轨道长度为什么等于极小多项式次数。',r'轨道元素都是极小多项式的根，故轨道长度不超过其次数。轨道根的乘积多项式被 Frobenius 固定，系数在基域中，并以原元素为根；极小多项式整除它，给出反向不等式。'),
13:(r'在 $\mathbb F_4/\mathbb F_2$ 中计算 $\theta$ 的迹和范数，其中 $\theta^2=\theta+1$。',r'$\operatorname{Tr}(\theta)=\theta+\theta^2=1$，$N(\theta)=\theta^3=\theta(\theta+1)=1$。$\operatorname{Tr}(1)=0$，但迹并非零映射。'),
14:(r'给出正规基存在性的一条线性代数证明路线。',r'令 $\sigma(z)=z^q$，把 $F$ 看作 $m$ 维 $K$ 向量空间。$\sigma^m=I$。若次数小于 $m$ 的非零多项式 $\sum c_iT^i$ 消去 $\sigma$，则非零线性化多项式 $\sum c_iz^{q^i}$ 在 $q^m$ 个点全部为零，但其次数至多 $q^{m-1}$，与根数界矛盾。故 $\sigma$ 的极小多项式次数为 $m$。使用线性代数中的循环向量定理（极小多项式次数等于空间维数时存在循环向量），可取 $\alpha$ 使 $\alpha,\sigma\alpha,\ldots,\sigma^{m-1}\alpha$ 为基，即正规基。'),
15:(r'分解 $\mathbb F_3$ 上的 $Q_8(x)$。',r'$Q_8=x^4+1=(x^2+x+2)(x^2+2x+2)$。两因子在 $\mathbb F_3$ 中均无根，故不可约。$\operatorname{ord}_8(3)=2$，与因子次数相符。'),
16:(r'在 $\operatorname{GF}(16)$、模多项式 $x^4+x+1$ 的模型中计算编码 $3\cdot7$ 和 $13/10$。',r'以编码 $2$（即 $x$）为本原元，有 $\log(3)=4$、$\log(7)=10$、$\operatorname{exp}(14)=9$；以及 $\log(13)=13$、$\log(10)=9$、$\operatorname{exp}(4)=3$。所以两结果为 $9,3$。指数按模 $15$ 运算，零元素需单独处理。'),
17:(r'证明有限非空网格上的任意函数都有逐变量次数受限的唯一插值代表。',r'对每个变量分别取 Lagrange 基多项式，再将它们相乘并按函数值加权，即得插值多项式，满足 $\deg_{x_i}f<|S_i|$。两个代表之差在网格上恒零，逐变量根数引理迫使差为零，故代表唯一。'),
18:(r'说明零和定理的合数情形如何从两个因子情形递推。',r'设 $n=ab$，$a,b\geq2$。从长度 $2ab-1$ 的序列依次选取 $2b-1$ 个互不相交的 $a$ 项组，使每组和被 $a$ 整除；选最后一组前剩余 $2a-1$ 项，因此各次都能应用 $a$ 的结论。将各组和除以 $a$ 得到 $2b-1$ 个整数，再应用 $b$ 的结论选出 $b$ 组，其并集有 $ab$ 项，和被 $ab$ 整除。$n=1$ 直接成立，素数情形由正文命题证明。'),
19:(r'证明非零多线性 $f\in\mathbb F_2[x_1,\ldots,x_n]$、$\deg f\leq d\leq n$ 至少有 $2^{n-d}$ 个非零取值点。',r'对 $n$ 归纳，写 $f=g+x_nh$。若 $h=0$，两层取值相同；$d\leq n-1$ 时由归纳得至少 $2\cdot2^{n-1-d}$ 个非零点，$d=n$ 时逐变量根数引理保证非零多线性多项式不可能在整个立方体恒零。若 $h\ne0$，则 $\deg h\leq d-1$，归纳给出至少 $2^{n-d}$ 个 $h$ 非零的输入，每个输入的 $g,g+h$ 恰有一个非零，所以仍有至少 $2^{n-d}$ 个非零点。零变量情形作为归纳起点。')
}
for n,(question,answer) in solutions.items():
 p=root/f'chapters/c{n:02}.md';s=p.read_text(encoding='utf-8')
 start=s.index('## 推理练习（新增）');end=s.index('## 原页对照与笔记',start)
 s=s[:start]+'## 推理练习（新增）\n\n'+question+'\n\n```{admonition} 展开解答（新增）\n:class: dropdown tip\n\n'+answer+'\n```\n\n'+s[end:]
 # Avoid pointers to absent notes in the corollary with its proof already supplied inline.
 if n==4:
  pattern=r'(^:::::\{container\} statement-box corollary\n:name: c04-statement-025\n.*?)(^:::::\s*$)'
  s=re.sub(pattern,lambda m:m[1].replace('证明要点见本框备注。','由有限性可知 $1$ 有有限加法阶；整环的正特征只能为素数。')+m[2],s,flags=re.M|re.S)
 p.write_text(s,encoding='utf-8')
print('Added 16 detailed proofs and formatted all 18 exercise solutions.')
